const SplitFlapDigit: React.FC<{
  currentNum: number;
  nextNum: number;
  fraction: number;
  width: number;
  height: number;
  color: string;
  bgColor: string;
}> = ({ currentNum, nextNum, fraction, width, height, color, bgColor }) => {
  const halfHeight = height / 2;
  const numStyles: React.CSSProperties = {
    fontFamily: interFamily,
    fontWeight: 700,
    fontSize: height * 0.8,
    color: color,
    position: "absolute",
    width: "100%",
    height: height,
    lineHeight: `${height}px`,
    textAlign: "center",
    letterSpacing: "-0.04em",
    transition: "none",
  };

  const overlayBase: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: "black",
    transition: "none",
    pointerEvents: "none",
  };

  return (
    <div
      style={{
        position: "relative",
        width,
        height,
        backgroundColor: bgColor,
        borderRadius: height * 0.15,
        overflow: "hidden",
        boxShadow: `0 ${height * 0.05}px ${height * 0.15}px rgba(0,0,0,0.08), inset 0 ${height * 0.02}px ${height * 0.05}px rgba(255,255,255,0.8)`,
        border: `2px solid rgba(0,0,0,0.05)`,
        perspective: `${height * 3}px`,
        transition: "none",
      }}
    >
      {/* Top Static Half (shows NEXT number) */}
      <div style={{ position: "absolute", top: 0, width: "100%", height: "50%", overflow: "hidden", backgroundColor: bgColor, borderBottom: `1px solid rgba(0,0,0,0.05)` }}>
        <div style={{ ...numStyles, top: 0 }}>{nextNum}</div>
        <div style={{ ...overlayBase, opacity: fraction * 0.1 }} />
      </div>

      {/* Bottom Static Half (shows CURRENT number) */}
      <div style={{ position: "absolute", top: "50%", width: "100%", height: "50%", overflow: "hidden", backgroundColor: bgColor, borderTop: `1px solid rgba(0,0,0,0.05)` }}>
        <div style={{ ...numStyles, top: "-100%" }}>{currentNum}</div>
        <div style={{ ...overlayBase, opacity: fraction * 0.2 }} />
      </div>

      {/* Flapping Half */}
      <div
        style={{
          position: "absolute",
          top: 0,
          width: "100%",
          height: "50%",
          transformOrigin: "bottom",
          transform: `rotateX(${-fraction * 180}deg)`,
          transformStyle: "preserve-3d",
          zIndex: 10,
          transition: "none",
        }}
      >
        {/* Flap Front (shows CURRENT number, top half) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            overflow: "hidden",
            backfaceVisibility: "hidden",
            backgroundColor: bgColor,
            borderBottom: `1px solid rgba(0,0,0,0.1)`,
            transition: "none",
          }}
        >
          <div style={{ ...numStyles, top: 0 }}>{currentNum}</div>
          <div style={{ ...overlayBase, opacity: fraction * 0.4 }} />
        </div>

        {/* Flap Back (shows NEXT number, bottom half) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            overflow: "hidden",
            backfaceVisibility: "hidden",
            backgroundColor: bgColor,
            transform: "rotateX(180deg)",
            borderTop: `1px solid rgba(0,0,0,0.1)`,
            transition: "none",
          }}
        >
          <div style={{ ...numStyles, top: "-100%" }}>{nextNum}</div>
          <div style={{ ...overlayBase, opacity: (1 - fraction) * 0.3 }} />
        </div>
      </div>

      {/* Center Hinge Line / Shadow Overlay */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: 0,
          width: "100%",
          height: height * 0.02,
          transform: "translateY(-50%)",
          background: "linear-gradient(to bottom, rgba(0,0,0,0.2) 0%, rgba(0,0,0,0) 100%)",
          zIndex: 20,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    </div>
  );
};

const RollingCounter: React.FC<{
  startValue: number;
  steps: number;
  steppedVal: number;
  width: number;
  height: number;
  color: string;
}> = ({ startValue, steps, steppedVal, width, height, color }) => {
  // Generate array of numbers from startValue down to startValue - steps
  const numbers = Array.from({ length: steps + 1 }).map((_, i) => startValue - i);

  return (
    <div
      style={{
        width,
        height,
        position: "relative",
        overflow: "hidden",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          transform: `translateY(${-steppedVal * height}px)`,
          position: "absolute",
          top: 0,
          transition: "none",
        }}
      >
        {numbers.map((num, i) => (
          <div
            key={i}
            style={{
              height,
              lineHeight: `${height}px`,
              fontFamily: interFamily,
              fontWeight: 700,
              fontSize: height * 0.8,
              color: color,
              textAlign: "center",
              letterSpacing: "-0.04em",
              transition: "none",
            }}
          >
            {num}
          </div>
        ))}
      </div>
      
      {/* Soft gradient fades at top and bottom to simulate a rolling cylinder */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "linear-gradient(to bottom, #F9F9F9 0%, transparent 25%, transparent 75%, #F9F9F9 100%)",
          pointerEvents: "none",
          transition: "none",
        }}
      />
      {/* Inset shadow for depth */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          borderRadius: height * 0.2,
          boxShadow: `inset 0 ${height * 0.05}px ${height * 0.1}px rgba(0,0,0,0.05), inset 0 -${height * 0.02}px ${height * 0.05}px rgba(0,0,0,0.02)`,
          pointerEvents: "none",
          border: "2px solid rgba(0,0,0,0.04)",
          transition: "none",
        }}
      />
    </div>
  );
};

const HealthCounters: React.FC<HealthCountersProps> = ({
  backgroundColor = "#F2F0ED",
  transparentBackground = false,
  durationInSeconds = 3,
  startWeight = 200,
  targetWeeks = 16,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timing
  const startFrame = fps * 0.4;
  const animDuration = fps * 1.8;
  const endFrame = startFrame + animDuration;

  // Continuous linear progress mapped to the total number of steps
  const linearVal = interpolate(frame, [startFrame, endFrame], [0, targetWeeks], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate stepped motion with mechanical snapping
  let stepIndex = Math.floor(linearVal);
  const tickProgress = linearVal % 1;
  let fraction = Easing.bezier(0.5, 0, 0.5, 1)(tickProgress);

  // Lock to final state perfectly at the end of the interpolation
  if (linearVal === targetWeeks) {
    stepIndex = targetWeeks - 1;
    fraction = 1;
  }

  const steppedVal = stepIndex + fraction;

  // Split Flap Logic
  const currentWeek = stepIndex;
  const nextWeek = stepIndex + 1;

  // Badge Animation
  const badgeStartFrame = endFrame + 5;
  const badgeScale = spring({ frame: frame - badgeStartFrame, fps, config: { damping: 14 } });
  const badgeOpacity = interpolate(frame, [badgeStartFrame, badgeStartFrame + 10], [0, 1], { extrapolateRight: "clamp" });

  const cardStyle: React.CSSProperties = {
    backgroundColor: "#FFFFFF",
    width: 900 * s,
    borderRadius: 64 * s,
    boxShadow: `0 ${30 * s}px ${60 * s}px rgba(0,0,0,0.04), 0 ${4 * s}px ${12 * s}px rgba(0,0,0,0.02)`,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    padding: `${80 * s}px 0`,
    position: "relative",
    transition: "none",
  };

  const iconColor = "#2C2C2E";
  const textColor = "#1C1C1E";
  const labelColor = "#4A4A4C";

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 60 * s, transition: "none" }}>
      
      {/* Top Card: Calendar Split Flap */}
      <div style={cardStyle}>
        <CalendarIcon size={100 * s} color={iconColor} />
        
        <div style={{ marginTop: 60 * s, marginBottom: 50 * s, transition: "none" }}>
          <div
            style={{
              padding: 24 * s,
              backgroundColor: "#EFEFF4",
              borderRadius: 36 * s,
              boxShadow: `inset 0 ${4 * s}px ${10 * s}px rgba(0,0,0,0.05)`,
              transition: "none",
            }}
          >
            <SplitFlapDigit
              currentNum={currentWeek}
              nextNum={nextWeek}
              fraction={fraction}
              width={460 * s}
              height={400 * s}
              color={textColor}
              bgColor="#F8F8F9"
            />
          </div>
        </div>

        <div style={{ fontFamily: interFamily, fontWeight: 700, fontSize: 52 * s, color: labelColor, letterSpacing: "0.15em", transition: "none" }}>
          WEEKS
        </div>
      </div>

      {/* Bottom Card: Weight Rolling Counter */}
      <div style={cardStyle}>
        <ScaleIcon size={100 * s} color={iconColor} />
        
        <div style={{ marginTop: 60 * s, display: "flex", alignItems: "baseline", transition: "none" }}>
          <div
            style={{
              backgroundColor: "#F9F9F9",
              borderRadius: 36 * s,
              padding: `${20 * s}px ${40 * s}px`,
              transition: "none",
            }}
          >
            <RollingCounter
              startValue={startWeight}
              steps={targetWeeks}
              steppedVal={steppedVal}
              width={420 * s}
              height={280 * s}
              color={textColor}
            />
          </div>
          <div style={{ fontFamily: interFamily, fontWeight: 600, fontSize: 64 * s, color: labelColor, marginLeft: 24 * s, transition: "none" }}>
            lbs
          </div>
        </div>

        {/* Success Badge */}
        <div
          style={{
            position: "absolute",
            bottom: -30 * s,
            backgroundColor: "#E8F5E9",
            color: "#2E7D32",
            fontFamily: interFamily,
            fontWeight: 600,
            fontSize: 44 * s,
            padding: `${20 * s}px ${40 * s}px`,
            borderRadius: 50 * s,
            display: "flex",
            alignItems: "center",
            gap: 16 * s,
            boxShadow: `0 ${10 * s}px ${20 * s}px rgba(46, 125, 50, 0.15)`,
            opacity: badgeOpacity,
            transform: `scale(${badgeScale}) translateY(${(1 - badgeOpacity) * 20 * s}px)`,
            transition: "none",
          }}
        >
          <svg width={40 * s} height={40 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
            <line x1="12" y1="5" x2="12" y2="19" />
            <polyline points="19 12 12 19 5 12" />
          </svg>
          {targetWeeks} lbs
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default HealthCounters;